arguments.cmd:
cat > /app/output/index.html <<'HTML'
<!doctype html>
<html lang="en">
  <head>
    <meta charset="UTF-8" />
    <meta name="viewport" content="width=device-width, initial-scale=1.0" />
    <title>DeployCloud Blog — Discover the latest in web development</title>
    <style>
      :root {
        --bg: #f7f9fc;
        --surface: #ffffff;
        --surface-soft: #f1f5fb;
        --text: #0c1222;
        --text-muted: #51607a;
        --border: #dfe6f2;
        --accent: #1877ff;
        --accent-soft: #e8f1ff;
        --shadow: 0 8px 30px rgba(13, 28, 68, 0.08);
        --radius: 16px;
      }

      * {
        box-sizing: border-box;
      }

      body {
        margin: 0;
        font-family: Inter, ui-sans-serif, system-ui, -apple-system, Segoe UI, Roboto, Helvetica, Arial, sans-serif;
        color: var(--text);
        background: linear-gradient(180deg, #ffffff 0%, var(--bg) 65%, #f2f6fc 100%);
        line-height: 1.55;
      }

      a {
        color: inherit;
        text-decoration: none;
      }

      .container {
        width: min(1200px, calc(100% - 2.5rem));
        margin: 0 auto;
      }

      .header-wrap {
        position: sticky;
        top: 0;
        z-index: 20;
        backdrop-filter: blur(10px);
        background: rgba(255, 255, 255, 0.86);
        border-bottom: 1px solid rgba(224, 232, 246, 0.9);
      }

      header {
        display: flex;
        align-items: center;
        justify-content: space-between;
        gap: 1rem;
        min-height: 72px;
      }

      .brand {
        font-weight: 800;
        font-size: 1.2rem;
        letter-spacing: -0.02em;
      }

      .brand span {
        color: var(--accent);
      }

      .nav {
        display: flex;
        align-items: center;
        gap: 0.75rem;
      }

      .nav-link,
      .nav-button {
        border: none;
        background: transparent;
        font: inherit;
        color: var(--text);
        font-weight: 600;
        padding: 0.5rem 0.75rem;
        border-radius: 10px;
        cursor: pointer;
      }

      .nav-link:hover,
      .nav-button:hover,
      .nav-button[aria-expanded="true"] {
        background: var(--surface-soft);
      }

      .dropdown {
        position: relative;
      }

      .mega {
        position: absolute;
        top: calc(100% + 0.75rem);
        left: 0;
        width: min(680px, 90vw);
        background: var(--surface);
        border: 1px solid var(--border);
        border-radius: 18px;
        box-shadow: var(--shadow);
        padding: 1.1rem;
        display: none;
        grid-template-columns: repeat(3, minmax(0, 1fr));
        gap: 0.9rem;
      }

      .mega.open {
        display: grid;
      }

      .mega-col {
        background: #fbfdff;
        border: 1px solid #ecf2fb;
        border-radius: 12px;
        padding: 0.75rem;
      }

      .mega-col h4 {
        margin: 0 0 0.45rem;
        font-size: 0.85rem;
        text-transform: uppercase;
        letter-spacing: 0.06em;
        color: #28406d;
      }

      .mega-col a {
        display: block;
        padding: 0.4rem 0;
        color: #344768;
        font-size: 0.93rem;
      }

      main {
        padding: 2.2rem 0 4rem;
      }

      .hero {
        margin-bottom: 2rem;
      }

      .hero h1 {
        font-size: clamp(1.9rem, 3.6vw, 3rem);
        line-height: 1.08;
        letter-spacing: -0.03em;
        margin: 0;
      }

      .hero p {
        max-width: 70ch;
        color: var(--text-muted);
        margin-top: 0.9rem;
        font-size: 1.05rem;
      }

      .category-row {
        display: flex;
        flex-wrap: wrap;
        gap: 0.65rem;
        margin: 1.4rem 0 1.2rem;
      }

      .pill {
        border: 1px solid var(--border);
        background: var(--surface);
        color: #34425e;
        border-radius: 999px;
        padding: 0.52rem 0.92rem;
        font-weight: 600;
        cursor: pointer;
      }

      .pill.active {
        background: var(--accent);
        color: white;
        border-color: var(--accent);
      }

      .search-wrap {
        margin-bottom: 2rem;
      }

      .search {
        width: min(420px, 100%);
        border: 1px solid var(--border);
        border-radius: 12px;
        padding: 0.72rem 0.88rem;
        font-size: 0.98rem;
        background: var(--surface);
      }

      .section-title {
        margin: 0 0 1rem;
        font-size: 1.35rem;
        letter-spacing: -0.02em;
      }

      .featured-grid {
        display: grid;
        grid-template-columns: 1.5fr 1fr 1fr;
        gap: 1rem;
        margin-bottom: 2.5rem;
      }

      .card {
        background: var(--surface);
        border: 1px solid var(--border);
        border-radius: var(--radius);
        padding: 1rem;
        box-shadow: 0 4px 20px rgba(9, 23, 50, 0.04);
        transition: transform 0.2s ease, box-shadow 0.2s ease;
      }

      .card:hover {
        transform: translateY(-3px);
        box-shadow: 0 14px 34px rgba(13, 30, 65, 0.13);
      }

      .featured-primary {
        background: linear-gradient(145deg, #f9fbff 0%, #eef4ff 100%);
      }

      .meta {
        display: flex;
        align-items: center;
        justify-content: space-between;
        margin-bottom: 0.7rem;
      }

      .tag {
        display: inline-flex;
        align-items: center;
        padding: 0.28rem 0.6rem;
        border-radius: 999px;
        background: var(--accent-soft);
        color: #1457c4;
        font-size: 0.76rem;
        font-weight: 700;
      }

      .date {
        color: var(--text-muted);
        font-size: 0.84rem;
      }

      .card h3 {
        margin: 0;
        font-size: 1.15rem;
        line-height: 1.25;
        letter-spacing: -0.02em;
      }

      .featured-primary h3 {
        font-size: 1.45rem;
      }

      .excerpt {
        color: var(--text-muted);
        margin-top: 0.65rem;
      }

      .stats {
        display: grid;
        grid-template-columns: repeat(3, minmax(0, 1fr));
        gap: 0.55rem;
        margin-top: 0.9rem;
      }

      .stat {
        background: rgba(24, 119, 255, 0.08);
        border: 1px solid rgba(24, 119, 255, 0.15);
        border-radius: 10px;
        padding: 0.55rem;
      }

      .stat strong {
        display: block;
        font-size: 1rem;
      }

      .author {
        margin-top: 0.95rem;
        display: flex;
        align-items: center;
        gap: 0.55rem;
        font-size: 0.89rem;
        color: #233352;
      }

      .avatar {
        width: 28px;
        height: 28px;
        border-radius: 50%;
        background: linear-gradient(135deg, #8ebcff, #396eff);
      }

      .latest-grid {
        display: grid;
        grid-template-columns: repeat(3, minmax(0, 1fr));
        gap: 1rem;
      }

      .post-title {
        font-size: 1.06rem;
      }

      .post-actions {
        margin-top: 1.7rem;
        display: flex;
        justify-content: center;
      }

      .btn {
        border: 1px solid var(--accent);
        background: var(--accent);
        color: white;
        font-weight: 700;
        border-radius: 999px;
        padding: 0.7rem 1.2rem;
        cursor: pointer;
      }

      .btn:disabled {
        opacity: 0.5;
        cursor: not-allowed;
      }

      .no-results {
        display: none;
        margin-top: 1rem;
        background: #fff6f6;
        border: 1px solid #ffd6d6;
        color: #832727;
        border-radius: 12px;
        padding: 0.9rem 1rem;
      }

      .cta {
        margin-top: 3rem;
        background: linear-gradient(130deg, #0d1f43, #103673);
        color: #e9f2ff;
        border-radius: 20px;
        padding: 1.8rem;
        display: flex;
        justify-content: space-between;
        align-items: center;
        gap: 1.1rem;
      }

      .cta h3 {
        margin: 0;
        font-size: 1.45rem;
      }

      .cta p {
        margin: 0.4rem 0 0;
        color: #c7d8f2;
      }

      footer {
        margin-top: 2.6rem;
        border-top: 1px solid var(--border);
        padding-top: 1.5rem;
        color: #5d6d87;
      }

      .footer-grid {
        display: grid;
        grid-template-columns: repeat(4, minmax(0, 1fr));
        gap: 1rem;
      }

      .footer-grid h4 {
        margin: 0 0 0.5rem;
        color: #20314f;
        font-size: 0.9rem;
      }

      .footer-grid a,
      .footer-grid div {
        display: block;
        margin: 0.3rem 0;
        font-size: 0.9rem;
      }

      @media (max-width: 1024px) {
        .featured-grid {
          grid-template-columns: 1fr 1fr;
        }

        .featured-primary {
          grid-column: span 2;
        }

        .latest-grid {
          grid-template-columns: repeat(2, minmax(0, 1fr));
        }
      }

      @media (max-width: 760px) {
        header {
          flex-wrap: wrap;
          padding: 0.6rem 0;
        }

        .featured-grid,
        .latest-grid,
        .footer-grid,
        .stats {
          grid-template-columns: 1fr;
        }

        .featured-primary {
          grid-column: auto;
        }

        .mega {
          left: auto;
          right: 0;
          width: min(420px, 94vw);
          grid-template-columns: 1fr;
        }

        .cta {
          flex-direction: column;
          align-items: flex-start;
        }
      }
    </style>
  </head>
  <body>
    <div class="header-wrap">
      <div class="container">
        <header>
          <a class="brand" href="#">Deploy<span>Cloud</span></a>
          <nav class="nav" aria-label="Primary navigation">
            <div class="dropdown" data-menu="products">
              <button class="nav-button" aria-expanded="false">Products</button>
              <div class="mega" role="menu" aria-label="Products menu">
                <div class="mega-col">
                  <h4>AI Cloud</h4>
                  <a href="#">Agentic Runtime</a>
                  <a href="#">Inference Gateway</a>
                  <a href="#">PromptOps</a>
                </div>
                <div class="mega-col">
                  <h4>Core Platform</h4>
                  <a href="#">Deployments</a>
                  <a href="#">Edge Functions</a>
                  <a href="#">Observability</a>
                </div>
                <div class="mega-col">
                  <h4>Security</h4>
                  <a href="#">Zero Data Retention</a>
                  <a href="#">Sandboxing</a>
                  <a href="#">Compliance</a>
                </div>
              </div>
            </div>

            <div class="dropdown" data-menu="resources">
              <button class="nav-button" aria-expanded="false">Resources</button>
              <div class="mega" role="menu" aria-label="Resources menu">
                <div class="mega-col">
                  <h4>Company</h4>
                  <a href="#">About</a>
                  <a href="#">Careers</a>
                  <a href="#">Press</a>
                </div>
                <div class="mega-col">
                  <h4>Learn</h4>
                  <a href="#">Docs</a>
                  <a href="#">Guides</a>
                  <a href="#">API Reference</a>
                </div>
                <div class="mega-col">
                  <h4>Open Source</h4>
                  <a href="#">GitHub</a>
                  <a href="#">Community</a>
                  <a href="#">Events</a>
                </div>
              </div>
            </div>

            <a class="nav-link" href="#">Blog</a>
            <a class="nav-link" href="#">Changelog</a>
          </nav>
        </header>
      </div>
    </div>

    <main>
      <div class="container">
        <section class="hero">
          <h1>DeployCloud Blog — Discover the latest in web development</h1>
          <p>
            Engineering insights, product updates, and practical stories from teams building with AI agents,
            cloud infrastructure, and modern developer tooling.
          </p>
        </section>

        <section id="category-filters">
          <div class="category-row" id="categoryRow"></div>
          <div class="search-wrap">
            <input id="searchInput" class="search" type="search" placeholder="Search posts by keyword, title, or category" aria-label="Search posts" />
          </div>
        </section>

        <section id="featured-articles">
          <h2 class="section-title">Featured Articles</h2>
          <div class="featured-grid" id="featuredGrid"></div>
        </section>

        <section id="latest-news">
          <h2 class="section-title">Latest News</h2>
          <div class="latest-grid" id="latestGrid"></div>
          <div class="no-results" id="noResults">No results found. Try another keyword or choose a different category.</div>
          <div class="post-actions">
            <button id="showMoreBtn" class="btn">Show more posts</button>
          </div>
        </section>

        <section class="cta" id="cta-banner">
          <div>
            <h3>Build with DeployCloud’s Agentic Infrastructure</h3>
            <p>Ship faster with secure sandboxes, durable execution, and unified AI gateway reporting.</p>
          </div>
          <button class="btn">Start building</button>
        </section>

        <footer>
          <div class="footer-grid">
            <div>
              <h4>Products</h4>
              <a href="#">AI Cloud</a>
              <a href="#">Core Platform</a>
              <a href="#">Security</a>
            </div>
            <div>
              <h4>Resources</h4>
              <a href="#">Docs</a>
              <a href="#">Guides</a>
              <a href="#">Blog</a>
            </div>
            <div>
              <h4>Company</h4>
              <a href="#">About</a>
              <a href="#">Careers</a>
              <a href="#">Legal</a>
            </div>
            <div>
              <h4>Status</h4>
              <div>All Systems Normal</div>
            </div>
          </div>
        </footer>
      </div>
    </main>

    <script>
      const categories = ["All Posts", "Engineering", "Community", "Company News", "Customers", "Security"];

      const featuredPosts = [
        {
          category: "Engineering",
          date: "March 18, 2026",
          title: "Agentic Infrastructure: 30% of deployments now start with coding agents",
          excerpt:
            "From CI handoffs to autonomous remediations, AI-native workflows are becoming default deployment paths on modern teams.",
          author: "Ava Patel",
          stats: [
            "30% of deployments initiated by coding agents",
            "1000% increase from six months ago",
            "20 times more likely to call AI inference"
          ]
        },
        {
          category: "Engineering",
          date: "March 10, 2026",
          title: "A new programming model for durable execution",
          excerpt: "How teams model long-running agent workflows with replay-safe state and deterministic retries.",
          author: "Noah Kim"
        },
        {
          category: "Security",
          date: "February 26, 2026",
          title: "Agent responsibly",
          excerpt: "Security guardrails, scoped credentials, and sandbox policies for AI-assisted production systems.",
          author: "Mila Reyes"
        }
      ];

      const allPosts = [
        {
          category: "Engineering",
          date: "March 10, 2026",
          title: "A new programming model for durable execution",
          excerpt: "Designing resilient workflows that survive retries, delays, and multi-step agent handoffs.",
          author: "Noah Kim"
        },
        {
          category: "Security",
          date: "March 4, 2026",
          title: "Zero Data Retention on AI Gateway",
          excerpt: "Minimize risk with stateless processing paths and strict retention controls for sensitive prompts.",
          author: "Jules Carter"
        },
        {
          category: "Engineering",
          date: "February 28, 2026",
          title: "Optimizing Sandbox snapshots",
          excerpt: "Cut warm-start latency with layered snapshots and workload-aware cache orchestration.",
          author: "Iris Nguyen"
        },
        {
          category: "Customers",
          date: "February 21, 2026",
          title: "How a startup made a blog platform work for humans and AI alike",
          excerpt: "Editorial and automation can coexist when publishing pipelines are designed for both personas.",
          author: "Rohan Sethi"
        },
        {
          category: "Engineering",
          date: "February 14, 2026",
          title: "Making build tool 96% faster with agents, sandboxes, and humans",
          excerpt: "A practical breakdown of hybrid automation patterns and benchmark methodology.",
          author: "Taylor Morgan"
        },
        {
          category: "Company News",
          date: "February 6, 2026",
          title: "Unified reporting for all AI Gateway usage",
          excerpt: "Track spend, latency, and model-level performance in one operational dashboard.",
          author: "Lina Chen"
        },
        {
          category: "Community",
          date: "January 31, 2026",
          title: "Inside the Agent Builders meetup series",
          excerpt: "What we learned from hands-on sessions with platform engineers across five cities.",
          author: "Mason Lee"
        },
        {
          category: "Customers",
          date: "January 22, 2026",
          title: "How fintech teams enforce secure agent workflows",
          excerpt: "Policy-as-code approaches for approvals, secrets handling, and auditable deployment trails.",
          author: "Hana Okafor"
        },
        {
          category: "Company News",
          date: "January 14, 2026",
          title: "DeployCloud raises platform limits for enterprise monorepos",
          excerpt: "New quotas and scaling controls support larger autonomous build and deploy pipelines.",
          author: "Evan Brooks"
        }
      ];

      const categoryRow = document.getElementById("categoryRow");
      const searchInput = document.getElementById("searchInput");
      const featuredGrid = document.getElementById("featuredGrid");
      const latestGrid = document.getElementById("latestGrid");
      const noResults = document.getElementById("noResults");
      const showMoreBtn = document.getElementById("showMoreBtn");
      const dropdowns = document.querySelectorAll(".dropdown");

      let activeCategory = "All Posts";
      let query = "";
      let visibleCount = 6;

      function renderFeatured() {
        featuredGrid.innerHTML = featuredPosts
          .map((post, index) => {
            const primary = index === 0 ? "featured-primary" : "";
            const statsBlock = post.stats
              ? `<div class="stats">${post.stats
                  .map((stat) => `<div class="stat"><strong>${stat.split(" ")[0]}</strong><span>${stat.replace(stat.split(" ")[0] + " ", "")}</span></div>`)
                  .join("")}</div>`
              : "";

            return `
              <article class="card ${primary}">
                <div class="meta">
                  <span class="tag">${post.category}</span>
                  <span class="date">${post.date}</span>
                </div>
                <h3>${post.title}</h3>
                <p class="excerpt">${post.excerpt}</p>
                ${statsBlock}
                <div class="author"><span class="avatar"></span>${post.author}</div>
              </article>
            `;
          })
          .join("");
      }

      function renderCategoryPills() {
        categoryRow.innerHTML = categories
          .map(
            (category) =>
              `<button class="pill ${category === activeCategory ? "active" : ""}" data-category="${category}">${category}</button>`
          )
          .join("");

        categoryRow.querySelectorAll(".pill").forEach((pill) => {
          pill.addEventListener("click", () => {
            activeCategory = pill.dataset.category;
            renderCategoryPills();
            renderLatest();
          });
        });
      }

      function filteredPosts() {
        return allPosts.filter((post) => {
          const byCategory = activeCategory === "All Posts" || post.category === activeCategory;
          const term = query.trim().toLowerCase();
          const byQuery =
            !term ||
            [post.title, post.excerpt, post.category, post.author].some((value) => value.toLowerCase().includes(term));
          return byCategory && byQuery;
        });
      }

      function renderLatest() {
        const matches = filteredPosts();
        const visible = matches.slice(0, visibleCount);

        latestGrid.innerHTML = visible
          .map(
            (post) => `
            <article class="card">
              <div class="meta">
                <span class="tag">${post.category}</span>
                <span class="date">${post.date}</span>
              </div>
              <h3 class="post-title">${post.title}</h3>
              <p class="excerpt">${post.excerpt}</p>
              <div class="author"><span class="avatar"></span>${post.author}</div>
            </article>
          `
          )
          .join("");

        noResults.style.display = matches.length === 0 ? "block" : "none";
        showMoreBtn.disabled = visible.length >= matches.length || matches.length === 0;
        showMoreBtn.textContent = showMoreBtn.disabled ? "All posts loaded" : "Show more posts";
      }

      searchInput.addEventListener("input", (event) => {
        query = event.target.value;
        visibleCount = 6;
        renderLatest();
      });

      showMoreBtn.addEventListener("click", () => {
        visibleCount += 3;
        renderLatest();
      });

      dropdowns.forEach((dropdown) => {
        const button = dropdown.querySelector(".nav-button");
        const menu = dropdown.querySelector(".mega");

        function openMenu() {
          dropdowns.forEach((d) => {
            d.querySelector(".mega").classList.remove("open");
            d.querySelector(".nav-button").setAttribute("aria-expanded", "false");
          });
          menu.classList.add("open");
          button.setAttribute("aria-expanded", "true");
        }

        function closeMenu() {
          menu.classList.remove("open");
          button.setAttribute("aria-expanded", "false");
        }

        button.addEventListener("click", (event) => {
          event.stopPropagation();
          const isOpen = menu.classList.contains("open");
          if (isOpen) closeMenu();
          else openMenu();
        });

        dropdown.addEventListener("mouseenter", openMenu);
        dropdown.addEventListener("mouseleave", closeMenu);
      });

      document.addEventListener("click", () => {
        dropdowns.forEach((dropdown) => {
          dropdown.querySelector(".mega").classList.remove("open");
          dropdown.querySelector(".nav-button").setAttribute("aria-expanded", "false");
        });
      });

      renderFeatured();
      renderCategoryPills();
      renderLatest();
    </script>
  </body>
</html>
HTML

